param([ValidateSet('Build','Map','Validate','Test','Package','Editor','Host','Join','Bootstrap')][string]$Action='Editor',[string]$EngineRoot='C:/Program Files/Epic Games/UE_5.8',[ValidatePattern('^VF-G5-[A-Za-z0-9_-]{1,48}$')][string]$BuildId='VF-G5-20261005-D')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot;$project=Join-Path $root 'VeilFallG0.uproject'
$v=Get-Content "$EngineRoot/Engine/Build/Build.version" -Raw|ConvertFrom-Json
if($v.MajorVersion-ne 5-or $v.MinorVersion-ne 8){throw 'Requires audited UE 5.8 line'}
$exe=Join-Path $root ('Builds/'+$BuildId+'/Windows/VeilFallG0/Binaries/Win64/VeilFallG0.exe')
switch($Action){
 Build {& "$PSScriptRoot/G0.ps1" Build -EngineRoot $EngineRoot;return}
 Map {& "$EngineRoot/Engine/Binaries/Win64/UnrealEditor-Cmd.exe" $project -run=pythonscript "-script=$root/Content/Python/create_g5.py" -unattended -nullrhi "-abslog=$root/Docs/Logs/G5-Map.log";if(!(Select-String -LiteralPath "$root/Docs/Logs/G5-Map.log" -SimpleMatch -Pattern G5_MAP_SUCCESS -Quiet)){throw 'Missing real map creation marker'}}
 Validate {& "$EngineRoot/Engine/Binaries/Win64/UnrealEditor-Cmd.exe" $project -run=pythonscript "-script=$root/Content/Python/validate_g5.py" -unattended -nullrhi "-abslog=$root/Docs/Logs/G5-Validate.log";if(!(Select-String -LiteralPath "$root/Docs/Logs/G5-Validate.log" -SimpleMatch -Pattern G5_AUTHORING_VALIDATE_PASS -Quiet)){throw 'Mission authoring validation failed'}}
 Test {& "$EngineRoot/Engine/Binaries/Win64/UnrealEditor-Cmd.exe" $project -unattended -nullrhi -nosplash '-ExecCmds=Automation RunTests VeilFallG0.' '-TestExit=Automation Test Queue Empty' "-abslog=$root/Docs/Logs/G5-Tests.log";if(@(Select-String -LiteralPath "$root/Docs/Logs/G5-Tests.log" -SimpleMatch -Pattern 'Result={Success}').Count-ne 15-or(Select-String -LiteralPath "$root/Docs/Logs/G5-Tests.log" -SimpleMatch -Pattern 'Result={Fail}' -Quiet)){throw 'Expected fifteen passing engine tests'}}
 Package {if(Test-Path "$root/Builds/$BuildId/Windows/VeilFallG0.exe"){throw 'Preserve candidate; use -BuildId with a new VF-G5- name before repackaging'};& $PSCommandPath Validate -EngineRoot $EngineRoot;$stage=Join-Path $env:LOCALAPPDATA ('VeilFallG5/Stage/'+[guid]::NewGuid());& "$EngineRoot/Engine/Build/BatchFiles/RunUAT.bat" BuildCookRun "-project=$project" -noP4 -platform=Win64 -clientconfig=Development -build -cook -stage "-stagingdirectory=$stage" -pak -archive "-archivedirectory=$root/Builds/$BuildId/Windows" -utf8output}
 Bootstrap {foreach($s in @('Build','Map','Validate','Test','Package')){& $PSCommandPath $s -EngineRoot $EngineRoot -BuildId $BuildId};return}
 default {$url='/Game/DeadSignal/L_DeadSignal_G5_Workshop?listen';if($Action-eq 'Join'){$url='127.0.0.1'};$args=$url+' -dx12 -windowed -ResX=1280 -ResY=720 -ExecCmds="sg.ViewDistanceQuality 1,sg.AntiAliasingQuality 2,sg.ShadowQuality 1,sg.GlobalIlluminationQuality 1,sg.ReflectionQuality 1,sg.PostProcessQuality 1,sg.TextureQuality 1,sg.EffectsQuality 1,sg.FoliageQuality 1,sg.ShadingQuality 1,t.MaxFPS 60" -ini:Engine:[TextureStreaming]:PoolSizeVRAMPercentage=0,[SystemSettings]:r.Streaming.PoolSize=768,[SystemSettings]:r.RenderTargetPoolMin=200,[SystemSettings]:r.ScreenPercentage=85';if($Action-eq 'Editor'){$exe="$EngineRoot/Engine/Binaries/Win64/UnrealEditor.exe";$args='"'+$project+'" '+$args.Replace('?listen','')+' -G5Preview -abslog="'+$root+'/Docs/Logs/G5-Editor-Open.log"'};if(!(Test-Path $exe)){throw "Missing executable $exe"};$style='Hidden';if($Action-eq 'Editor'){$style='Normal'};Start-Process $exe -ArgumentList $args -WindowStyle $style;return}
}
if($LASTEXITCODE-ne 0){throw "$Action failed: $LASTEXITCODE"}

